-- Generated by scripts/generate-seed-sql.ts — do not edit by hand.
-- Loads the 2023 print catalogue into an empty database.
--
-- Run this in the Supabase SQL editor AFTER schema.sql. It is safe to run
-- more than once: existing codes are left exactly as they are, so prices you
-- have already set are never overwritten.
--
-- Products arrive published with no price, which the shop renders as
-- "price on request". Set a price and the line starts showing a real figure.

begin;

-- Ranges. Products reference these by foreign key, so they go first.
on conflict (id) do update set
  name = excluded.name,
  short_name = excluded.short_name,
  kicker = excluded.kicker,
  tagline = excluded.tagline,
  hero_image = excluded.hero_image,
  thumb = excluded.thumb,
  theme = excluded.theme,
  sort_order = excluded.sort_order;

-- 39 product codes, straight off the print catalogue.
on conflict (code) do nothing;

commit;

-- What landed:
select (select count(*) from public.categories) as ranges,
       (select count(*) from public.products) as products,
       (select count(*) from public.products where price is not null) as priced;
